import { describe, it, expect } from 'vitest';
import * as fs from 'node:fs';
import * as path from 'node:path';

/**
 * Guard over `src/tiLogicVisualizer/signatures/_index.json`.
 *
 * The file was once generated by `scripts/extract-signatures.cjs`, but has for a
 * long time been maintained by hand — the generator no longer runs (it
 * looks for a map literal `KNOWN_SIGNATURES` that no longer exists since the switch to
 * `new Map()` + runtime registration). Hand maintenance drifts:
 * on 2026-08-14 the index listed 42 sections for 44 files on disk
 * (two whole categories with 75 entries were missing), nine `count` fields were
 * wrong and `totalEntries` stood at 503 instead of 563.
 *
 * This test does not need the generator: it checks the index against the files
 * that sit next to it. That way every gap in hand maintenance shows up immediately,
 * regardless of whether the generator ever runs again.
 */
const DIR = path.resolve(__dirname, '..', 'tiLogicVisualizer', 'signatures');

interface Section { index: number; slug: string; title: string; count: number; file: string }
interface Index { totalEntries: number; infSentinel: unknown; sections: Section[] }

const idx: Index = JSON.parse(fs.readFileSync(path.join(DIR, '_index.json'), 'utf8'));
const filesOnDisk = fs.readdirSync(DIR).filter(f => f !== '_index.json').sort();

describe('signatures/_index.json stays congruent with the category files', () => {
  it('lists every file exactly once', () => {
    expect(idx.sections.map(s => s.file).sort()).toEqual(filesOnDisk);
  });

  it('refers to no file that does not exist', () => {
    const missing = idx.sections.filter(s => !fs.existsSync(path.join(DIR, s.file)));
    expect(missing.map(s => s.file)).toEqual([]);
  });

  it('states the actual number of entries for each section', () => {
    const wrong = idx.sections
      .map(s => {
        const entries = JSON.parse(fs.readFileSync(path.join(DIR, s.file), 'utf8')).entries as unknown[];
        return { file: s.file, indexed: s.count, real: entries.length };
      })
      .filter(r => r.indexed !== r.real);
    expect(wrong).toEqual([]);
  });

  it('sums the sections to totalEntries', () => {
    expect(idx.totalEntries).toBe(idx.sections.reduce((a, s) => a + s.count, 0));
  });

  it('derives index and slug from the file name', () => {
    const wrong = idx.sections.filter(s => s.file !== `${String(s.index).padStart(2, '0')}-${s.slug}.json`);
    expect(wrong.map(s => s.file)).toEqual([]);
  });
});
